package com.bank.charge.service;

import com.bank.charge.model.ChargeNode;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Counts downward charge runs that sum to the flagged amount using prefix sums.
public class CountPathsService {
    private static final Logger log = Logger.getLogger(CountPathsService.class.getName());

    public int countFlaggedRuns(ChargeNode root, BigDecimal flagged) {
        // Key the map on exact long-cents to keep hashing precise.
        long target = toCents(flagged);
        Map<Long, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0L, 1); // empty prefix lets a run start at the root
        int count = dfs(root, 0L, target, prefixCounts);
        log.info(() -> "Total flagged runs = " + count);
        return count;
    }

    private int dfs(ChargeNode node, long currentSum, long target, Map<Long, Integer> prefixCounts) {
        if (node == null) {
            return 0;
        }
        currentSum += toCents(node.getAmount());
        // Runs ending here = number of earlier prefixes equal to currentSum - target.
        long needed = currentSum - target;
        int here = prefixCounts.getOrDefault(needed, 0);
        if (here > 0) {
            long cs = currentSum;
            log.fine(() -> "At sum(cents)=" + cs + " found " + here + " matching run(s)");
        }
        // Record this prefix for descendants.
        prefixCounts.merge(currentSum, 1, Integer::sum);

        int total = here
                + dfs(node.getLeft(), currentSum, target, prefixCounts)
                + dfs(node.getRight(), currentSum, target, prefixCounts);

        // Roll back so sibling branches never see this prefix.
        prefixCounts.merge(currentSum, -1, Integer::sum);
        return total;
    }

    private long toCents(BigDecimal rupees) {
        return rupees.movePointRight(2).longValueExact();
    }
}
