package com.bank.charge;

import com.bank.charge.model.ChargeNode;
import com.bank.charge.service.CountPathsService;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class CountPathsApplication {
    private static final Logger log = Logger.getLogger(CountPathsApplication.class.getName());

    public static void main(String[] args) {
        // Charge tree where flagged amount is 100.
        //   root 100 ; left -50 -> 150 (run -50,150=100) ; right 50 -> 50 (run 50,50=100)
        ChargeNode root = new ChargeNode(new BigDecimal("100"));
        ChargeNode l = new ChargeNode(new BigDecimal("-50"));
        ChargeNode r = new ChargeNode(new BigDecimal("50"));
        ChargeNode ll = new ChargeNode(new BigDecimal("150"));
        ChargeNode rr = new ChargeNode(new BigDecimal("50"));
        root.setLeft(l); root.setRight(r);
        l.setLeft(ll); r.setLeft(rr);

        CountPathsService service = new CountPathsService();
        log.info("Flagged runs summing to 100 (NBI fraud scan): "
                + service.countFlaggedRuns(root, new BigDecimal("100")));
    }
}
